// Only these spreadsheets (both are team COPIES, never the live Sheet), only a tab read or a cell-value batch update. Everything else is refused.
const ALLOWED_SPREADSHEETS = [
  '14lXRsWoEY63tOsz4SwggiItgTNPFWI4KDVTLay3MLDw', // original STAGING COPY
  '11HXJsfGHIqnr_mekiV6l277v61C2qz_ELNxA0RyaNcA', // Copy - Nov 11 version (added 11/11)
];
const r = $input.first().json.body || {};
const q = r.query || {};
const read = r.method === 'GET' && r.suffix === '' && r.body == null;
const write = r.method === 'POST' && r.suffix === ':batchUpdate' && r.body && Array.isArray(r.body.requests)
  && r.body.requests.length > 0 && r.body.requests.length <= 3
  && r.body.requests.every(x => Object.keys(x).length === 1 && x.updateCells && x.updateCells.fields === 'userEnteredValue');
const queryOk = Object.keys(q).every(k => k === 'ranges' || k === 'fields');
if (!ALLOWED_SPREADSHEETS.includes(r.spreadsheetId) || !(read || write) || !queryOk) {
  return [{ json: { allowed: false } }];
}
const qs = Object.entries(q).map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(v)).join('&');
const url = 'https://sheets.googleapis.com/v4/spreadsheets/' + r.spreadsheetId + (write ? ':batchUpdate' : '') + (qs ? '?' + qs : '');
return [{ json: { allowed: true, write, url, payload: r.body } }];

// Hand Google's status and JSON back unchanged; the backend decides what they mean.
const r = $input.first().json;
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
return [{ json: { status: r.statusCode, body: body && typeof body === 'object' ? body : {} } }];
